import type { RequestHandler } from './$types';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import {
  getFilterOptions,
  getHeroStats,
  getDelayDistribution,
  getDayOfWeekDistribution,
  getHourDistribution,
  getBusiestDays,
  getWorstDays,
  getRouteStats,
  getFlightNumberStats,
  getAircraftStats,
  getTopDelays,
  getDailyOtpStats,
  getMonthlyBreakdown,
  getWindDelayStats,
  getVisibilityDelayStats,
  getPrecipitationDelayStats,
  getWeatherCodeDelayStats,
  getCrosswindDelayStats,
  getWorstWeatherDays,
  getDelayImpact,
  getWorstDelayDays,
} from '../../../../stats/lib/queries';
import type { FilterConfig } from '../../../../stats/lib/types';

/**
 * Mirrors the stats page load function — reuses all existing query functions.
 * Query params: range, dateFrom, dateTo, airline, route, direction, dow, season, month, year, threshold
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const range = url.searchParams.get('range') ?? '90';
    const dateFrom = url.searchParams.get('dateFrom') ?? '';
    const dateTo = url.searchParams.get('dateTo') ?? '';
    const activeAirline = url.searchParams.get('airline') ?? '';
    const activeRoutes = url.searchParams.getAll('route').filter(Boolean);
    const activeDirection = url.searchParams.get('direction') ?? '';
    const activeDow = url.searchParams.get('dow') ?? '';
    const activeSeason = url.searchParams.get('season') ?? '';
    const activeMonth = url.searchParams.get('month') ?? '';
    const activeYear = url.searchParams.get('year') ?? '';
    const thresholdParam = parseInt(url.searchParams.get('threshold') ?? '15', 10);
    const threshold = [0, 15, 30].includes(thresholdParam) ? thresholdParam : 15;
    const minFlightsPerRoute = range === '30' ? 2 : range === '90' ? 3 : 5;

    const parsedRoutes = activeRoutes.map(r => {
      const parts = r.split('-');
      const dep = parts[0] ?? '';
      const arr = parts.slice(1).join('-');
      return { dep, arr, key: r };
    }).filter(r => r.dep && r.arr);

    const dowNum = parseInt(activeDow, 10);
    const monthNum = parseInt(activeMonth, 10);
    const yearNum = parseInt(activeYear, 10);

    const filterConfig: FilterConfig = {
      range: {
        type: range as '30' | '90' | 'custom' | 'all',
        dateFrom: dateFrom || undefined,
        dateTo: dateTo || undefined,
      },
      airline: activeAirline || undefined,
      routes: parsedRoutes.length > 0 ? parsedRoutes : undefined,
      direction: activeDirection as 'dep' | 'arr' | '' || undefined,
      dow: activeDow !== '' && !isNaN(dowNum) && dowNum >= 0 && dowNum <= 6 ? dowNum : undefined,
      season: activeSeason as 'summer' | 'winter' | 'spring' | 'autumn' | '' || undefined,
      month: activeMonth !== '' && !isNaN(monthNum) && monthNum >= 1 && monthNum <= 12 ? monthNum : undefined,
      year: activeYear !== '' && !isNaN(yearNum) && yearNum >= 2000 && yearNum <= 2100 ? yearNum : undefined,
      threshold,
      minFlightsPerRoute,
    };

    const [
      filterOptions,
      heroStats,
      delayDistribution,
      dayOfWeek,
      departureHour,
      busiestDays,
      worstDays,
      worstRoutes,
      flightNumbers,
      aircraftUsage,
      topDelays,
      dailyOtp,
      monthlyBreakdown,
      windDelays,
      visibilityDelays,
      precipDelays,
      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    ] = await Promise.all([
      getFilterOptions(),
      getHeroStats(filterConfig),
      getDelayDistribution(filterConfig),
      getDayOfWeekDistribution(filterConfig),
      getHourDistribution(filterConfig),
      getBusiestDays(filterConfig, 10),
      getWorstDays(filterConfig, 10),
      getRouteStats(filterConfig),
      getFlightNumberStats(filterConfig, 20),
      getAircraftStats(filterConfig),
      getTopDelays(filterConfig, 10),
      getDailyOtpStats(filterConfig),
      getMonthlyBreakdown(filterConfig),
      getWindDelayStats(filterConfig),
      getVisibilityDelayStats(filterConfig),
      getPrecipitationDelayStats(filterConfig),
      getWeatherCodeDelayStats(filterConfig),
      getCrosswindDelayStats(filterConfig),
      getWorstWeatherDays(filterConfig, 10),
      getDelayImpact(filterConfig),
      getWorstDelayDays(filterConfig, 10),
    ]);

    const data = {
      filterConfig,
      filterOptions,
      heroStats,
      delayDistribution,
      dayOfWeek,
      departureHour,
      busiestDays,
      worstDays,
      worstRoutes,
      flightNumbers,
      aircraftUsage,
      topDelays,
      dailyOtp,
      monthlyBreakdown,
      windDelays,
      visibilityDelays,
      precipDelays,
      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/stats]', err);
    return debugError('Query failed', 500);
  }
};

/**
 * Shared helpers for /api/debug/* endpoints.
 * Server-only — never imported client-side.
 */

/**
 * Structured JSON response with metadata.
 * Every debug endpoint wraps its data in this shape.
 */
export function debugResponse(
  rows: unknown[],
  queryMs: number,
): Response {
  return new Response(
    JSON.stringify({
      rows,
      count: rows.length,
      queryMs: Math.round(queryMs),
    }),
    {
      status: 200,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Error response for client errors (bad params, auth failures).
 */
export function debugError(message: string, status = 400): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Parse and clamp pagination params from URL search params.
 * Returns { limit, offset } with enforced caps.
 */
export function parsePagination(
  searchParams: URLSearchParams,
  defaults: { defaultLimit?: number; maxLimit?: number } = {},
): { limit: number; offset: number } {
  const defaultLimit = defaults.defaultLimit ?? 100;
  const maxLimit = defaults.maxLimit ?? 1000;

  const rawLimit = parseInt(searchParams.get('limit') ?? '', 10);
  const limit = Math.min(
    Math.max(1, isNaN(rawLimit) ? defaultLimit : rawLimit),
    maxLimit,
  );
  const rawOffset = parseInt(searchParams.get('offset') ?? '', 10);
  const offset = Math.max(0, isNaN(rawOffset) ? 0 : rawOffset);

  return { limit, offset };
}

/** SQL commands allowed by the debug SQL endpoint */
const ALLOWED_COMMANDS = new Set(['SELECT', 'EXPLAIN', 'SHOW', 'DESCRIBE', 'WITH']);

/** Keywords that are blocked even inside otherwise-allowed statements */
const DANGEROUS_KEYWORDS = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE'];

/**
 * Validate a SQL query string for the debug endpoint.
 * Returns { valid: true } or { valid: false, error: string }.
 */
export function validateSqlQuery(query: string): { valid: true } | { valid: false; error: string } {
  const firstToken = query.split(/\s+/)[0]?.toUpperCase() ?? '';
  if (!ALLOWED_COMMANDS.has(firstToken)) {
    return { valid: false, error: `Statement type "${firstToken}" not allowed. Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH are permitted.` };
  }

  const upperQuery = query.toUpperCase();
  for (const keyword of DANGEROUS_KEYWORDS) {
    if (new RegExp(`\\b${keyword}\\b`).test(upperQuery)) {
      return { valid: false, error: `Dangerous keyword "${keyword}" detected in query. Only read-only statements are allowed.` };
    }
  }

  return { valid: true };
}

/**
 * Validate a Bearer token for the debug API.
 * Returns true if the Authorization header matches the expected token.
 */
export function validateDebugToken(
  authHeader: string | null,
  expectedToken: string | undefined,
): boolean {
  if (!expectedToken || !authHeader) return false;
  return authHeader === `Bearer ${expectedToken}`;
}

